function makeResponseSection(item){const box=document.createElement('section');box.className='sl-response-section';const h=document.createElement('h2');h.textContent=semanticLabel(item.title);box.append(h);if(semanticLabel(item.title)!==item.title){const sourceHead=document.createElement('h3');sourceHead.className='sl-response-source-heading';sourceHead.textContent='Source section: '+item.title;box.append(sourceHead)}item.blocks.forEach(n=>box.append(n.cloneNode(true)));return box}
runSearch=async function(q){q=String(q||'').trim();const status=$('#slSearchStatus'),out=$('#slSearchResults');if(q.length<2){status.hidden=true;out.innerHTML=recentSearches();return}data.queries=[q,...data.queries.filter(x=>key(x)!==key(q))].slice(0,8);save();status.hidden=false;status.textContent='Finding a relevant source…';out.innerHTML='<div class="sl-loading-row"><i></i><i></i><i></i></div>';try{const found=await search(q),items=Array.isArray(found.pages)?found.pages:[];if(!items.length){status.textContent='No source pages matched “'+q+'”.';out.innerHTML='<div class="sl-empty"><strong>No results found</strong><p>Try a shorter phrase or a related subject.</p></div>';return}const queryKey=key(q),ranked=[...items].sort((a,b)=>{const score=x=>{const title=key(x.title||x.key);return title===queryKey?0:title.startsWith(queryKey)?1:title.includes(queryKey)?2:3};return score(a)-score(b)}),best=ranked[0],alternatives=ranked.slice(1,6).map(x=>clean(x.title||x.key)).filter(Boolean);status.textContent='Preparing a structured, source-based response…';openArticle(clean(best.title||best.key),plain(best.description||best.excerpt||''),image(best.thumbnail?.url),alternatives)}catch(e){status.textContent='Wikipedia search is temporarily unavailable.';out.innerHTML='<div class="sl-error"><strong>Search could not be completed</strong><p>'+esc(e.message||'Check your connection and try again.')+'</p><button class="sl-secondary" data-retry="'+esc(q)+'">Try again</button></div>'}};
