// Reliable, source-attributed study response formatter.
sourceBlocks=function(root){
 const lead=[],sections=[];let current=null;
 const add=(target,node)=>{if(node.tagName==='P'&&node.textContent.length>1150&&!node.querySelector('a, sup, .reference')){const sentences=(node.textContent||'').match(/[^.!?]+(?:[.!?]+|$)/g)||[node.textContent];let part='';for(const sentence of sentences){if(part.length+sentence.length>820&&part){const p=document.createElement('p');p.textContent=part.trim();target.push(p);part=''}part+=sentence}if(part.trim()){const p=document.createElement('p');p.textContent=part.trim();target.push(p)}}else target.push(node.cloneNode(true))};
 for(const node of root.querySelectorAll('h2,h3,h4,p,ul,ol,blockquote,table,figure,dl')){
  if(/^H[234]$/.test(node.tagName)){const title=plain(node.textContent).replace(/\[edit\]/ig,'').trim();if(responseStopTitles.test(title)){current=null;continue}if(title){current=sections.find(x=>key(x.title)===key(title));if(!current){current={title,level:Number(node.tagName.slice(1)),blocks:[]};sections.push(current)}}continue}
  if(!node.textContent?.trim()&&!node.querySelector('img'))continue;
  const ancestor=node.parentElement?.closest('p,ul,ol,blockquote,table,figure,dl');if(ancestor&&ancestor!==node)continue;
  add(current?current.blocks:lead,node);
 }
 return{lead,sections:sections.filter(s=>s.blocks.length)};
};
makeResponseSection=function(item){
 const box=document.createElement('section');box.className='sl-response-section';
 const heading=document.createElement('h2');heading.textContent=semanticLabel(item.title);box.append(heading);
 if(semanticLabel(item.title)!==item.title){const sourceHead=document.createElement('p');sourceHead.className='sl-response-source-heading';sourceHead.textContent='From the source: '+item.title;box.append(sourceHead)}
 item.blocks.forEach(n=>{const clone=n.cloneNode(true);if(clone.tagName==='TABLE'){const frame=document.createElement('div');frame.className='sl-table-wrap';frame.setAttribute('role','region');frame.setAttribute('aria-label','Scrollable comparison table');frame.tabIndex=0;frame.append(clone);box.append(frame)}else box.append(clone)});
 if(/example|application|case stud/i.test(item.title))box.classList.add('sl-response-example');
 if(/definition|meaning/i.test(item.title))box.classList.add('sl-response-definition');
 return box;
};
