 if(mode==='quick'&&sections.length){const points=document.createElement('section');points.className='sl-response-section sl-response-keypoints';const h=document.createElement('h2');h.textContent='Key ideas';points.append(h);const ul=document.createElement('ul');const picks=[...sections].filter(x=>x!==def).sort((a,b)=>sectionRank(a.title)-sectionRank(b.title)).slice(0,6);picks.forEach(x=>{const li=document.createElement('li');const strong=document.createElement('strong');strong.textContent=semanticLabel(x.title)+': ';const span=document.createElement('span');span.textContent=sectionSentence(x)||'See the source section for details.';li.append(strong,span);ul.append(li)});points.append(ul);wrap.append(points);const recap=document.createElement('section');recap.className='sl-response-callout sl-response-revision';const rh=document.createElement('h2');rh.textContent='Review';const rp=document.createElement('p');rp.textContent='Use the key ideas above as prompts, then open the cited source sections to check the supporting detail.';recap.append(rh,rp);wrap.append(recap)}
 else if(sections.length){let chosen=sections;if(mode==='smart'&&sections.length>7){const ranked=[...sections].filter(x=>x!==def).sort((a,b)=>sectionRank(a.title)-sectionRank(b.title));chosen=ranked.slice(0,7).sort((a,b)=>sections.indexOf(a)-sections.indexOf(b));if(def)chosen=[def,...chosen.filter(x=>x!==def)].slice(0,7)}chosen.filter(x=>x!==def||mode==='detailed').forEach(x=>wrap.append(makeResponseSection(x)))}
