 if(topicNames.length){const box=document.createElement('section');box.className='sl-response-related';const h=document.createElement('h2');h.textContent='Related topics';box.append(h);const row=document.createElement('div');topicNames.forEach(name=>{const b=document.createElement('button');b.type='button';b.dataset.open=name;b.textContent=name;row.append(b)});box.append(row);wrap.append(box)}
 appendSourceSection(wrap);body.append(wrap);body.hidden=false;$('#slShell').hidden=true;$('#slReader').hidden=false;page.classList.add('reading','response-view');$('#slOriginalPanel').hidden=true;$('#slOverview').hidden=true;const nav=page.querySelector('.sl-related');if(nav)nav.hidden=true;
 page.querySelectorAll('[data-reader-mode]').forEach(b=>{const active=b.dataset.readerMode===mode;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));b.setAttribute('aria-pressed',String(active))});
 const toc=$('#slToc'),hs=[...body.querySelectorAll('h2,h3')];if(toc)toc.innerHTML=hs.map((h,i)=>{h.id='sl-head-'+i;return '<a href="#'+h.id+'">'+esc(h.textContent)+'</a>'}).join('')||'<span class="sl-muted">No response sections are available.</span>';
